-- ==============================================================================
-- KS STORE - SEED DATA (Datos iniciales para Supabase SQL Editor)
-- ==============================================================================

-- 1. INSERTAR CATEGORÍAS
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name;

-- 2. INSERTAR CONFIGURACIÓN DE TIENDA
ON CONFLICT (id) DO UPDATE SET whatsapp_number = EXCLUDED.whatsapp_number, instagram_url = EXCLUDED.instagram_url, facebook_url = EXCLUDED.facebook_url;

-- 3. INSERTAR PRODUCTOS
ON CONFLICT (slug) DO UPDATE SET price = EXCLUDED.price, stock = EXCLUDED.stock;
